    "name": "quiz.py",
    "title": "A quiz: a class, a loop, and a score. Good for testing input(), not ju",
    "code": "# A quiz: a class, a loop, and a score. Good for testing input(), not just print().\nQUESTIONS = [\n    (\"What is 7 * 6?\", \"42\"),\n    (\"What is the capital of Pakistan?\", \"islamabad\"),\n    (\"Which language is this app written in?\", \"python\"),\n]\n\n\nclass Quiz:\n    def __init__(self, questions):\n        self.questions = questions\n        self.score = 0\n\n    def ask_all(self):\n        for number, (question, expected) in enumerate(self.questions, start=1):\n            answer = input(f\"{number}. {question} \")\n            self.check(answer, expected)\n\n    def check(self, answer, expected):\n        if answer.strip().lower() == expected:\n            self.score += 1\n            print(\"Correct.\")\n        else:\n            print(f\"Not quite. The answer is {expected}.\")\n\n    def finish(self):\n        total = len(self.questions)\n        print(f\"\\nScore: {self.score} of {total}\")\n        if self.score == total:\n            print(\"Perfect.\")\n\n\nquiz = Quiz(QUESTIONS)\nquiz.ask_all()\nquiz.finish()\n"
